package com.example.starter.domain;

/**
 * 长短款挂账状态：OPEN 挂账中；SETTLED 已在 3 个自然日内销账；ESCALATED 逾期升级并冻结责任人新任务。
 */
public enum DiscrepancyStatus {
    OPEN,
    SETTLED,
    ESCALATED
}

package com.example.starter.support;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.time.Clock;

/**
 * 时钟配置：统一使用 UTC 时钟，业务代码通过注入 {@link Clock} 取当前时刻，
 * 测试中替换为可控时钟以验证 4 小时押运时限与第 3 日销账边界。
 */
@Configuration
public class ClockConfig {

    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.service;

/**
 * 业务规则异常：由统一异常处理映射为 409（规则冲突）或指定状态码。
 */
public class BusinessException extends RuntimeException {

    private final int statusCode;

    public BusinessException(String message) {
        this(409, message);
    }

    public BusinessException(int statusCode, String message) {
        super(message);
        this.statusCode = statusCode;
    }

    public int getStatusCode() {
        return statusCode;
    }
}

package com.example.starter.service;

import org.springframework.stereotype.Service;

/**
 * ATM 加钞计划与双人押运核销服务（骨架，逐步填充）。
 */
@Service
public class ReplenishService {
}

