package com.example.starter.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 预测编制加钞计划请求。amount 为空时按 ATM 历史日均取现预测；
 * 非空时使用指定金额（仍不得超过钞箱容量，恰等容量合法）。
 */
public record CreatePlanRequest(
        @NotBlank String requestId,
        @NotBlank String atmCode,
        Long amount
) {
}

package com.example.starter.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 审批请求：审批通过后开始计算 4 小时押运时限。
 */
public record ApproveRequest(
        @NotBlank String requestId
) {
}

package com.example.starter.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 押运打卡请求：两名不同押运员先后打卡，按到达时刻定序；同人重复打卡拒绝。
 */
public record CheckinRequest(
        @NotBlank String requestId,
        @NotBlank String custodianCode
) {
}

package com.example.starter.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * 双人清点请求：countedAmount 为两人共同清点确认数；custodianCode 为清点责任人（押运组长），
 * 发生长短款时作为挂账责任人，逾期销账将冻结其新任务。
 */
public record CountRequest(
        @NotBlank String requestId,
        @NotNull @PositiveOrZero Long countedAmount,
        @NotBlank String custodianCode
) {
}

package com.example.starter.api;

import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * 设备确认请求：deviceAmount 为设备实际入账数。与清点数、计划数三方一致方可核销。
 */
public record DeviceConfirmRequest(
        @NotNull String requestId,
        @NotNull @PositiveOrZero Long deviceAmount
) {
}

package com.example.starter.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 长短款销账请求：须在挂账发生日起 3 个自然日内（UTC 日界）提交，恰第 3 日受理，逾期升级冻结责任人。
 */
public record SettleDiscrepancyRequest(
        @NotBlank String requestId
) {
}

package com.example.starter.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 日结封存请求：封存为终态；对已封存单重复封存返回幂等成功，封存后的迟到数据只记迟到事件。
 */
public record SealRequest(
        @NotBlank String requestId
) {
}

