        f1.get(10, TimeUnit.SECONDS);
        f2.get(10, TimeUnit.SECONDS);
        pool.shutdown();

        var checkins = repo.findCheckins(id);
        assertEquals(2, checkins.size());
        assertEquals(1, checkins.get(0).seq());
