/** 单条幂等留痕插入；并发同键可能抛唯一键冲突，由服务层捕获裁决，不加独立事务边界。 */
public long insertIdempotent(String requestId, String action, String fingerprint,
                             Long planId, int statusCode, String responseBody, Instant now) {
    KeyHolder keyHolder = new GeneratedKeyHolder();
    jdbc.update(con -> {
        PreparedStatement ps = con.prepareStatement(
                "INSERT INTO idempotent_request (request_id, action, fingerprint, plan_id, status_code, "
                        + "response_body, created_at) VALUES (?,?,?,?,?,?,?)", Statement.RETURN_GENERATED_KEYS);
        ps.setString(1, requestId);
        ps.setString(2, action);
        ps.setString(3, fingerprint);
        if (planId == null) {
            ps.setNull(4, Types.BIGINT);
        } else {
            ps.setLong(4, planId);
        }
        ps.setInt(5, statusCode);
        ps.setString(6, responseBody);
        ps.setTimestamp(7, Timestamp.from(now));
        return ps;
    }, keyHolder);
    Number key = keyHolder.getKey();
    return key == null ? 0L : key.longValue();
}

