/**
 * 以 requestId 为键执行动作。同键同指纹返回首次结果；同键异指纹抛 409；
 * 首次成功结果与留痕在同一事务提交。并发同键由主键约束裁决。
 */
private Outcome withIdempotency(String requestId, String action, String fingerprint,
                                Long planId, java.util.function.Supplier<Outcome> task) {
    Optional<IdempotentRow> existing = repo.findIdempotent(requestId);
    if (existing.isPresent()) {
        IdempotentRow row = existing.get();
        if (!row.fingerprint().equals(fingerprint)) {
            throw new BusinessException(409,
                    "requestId=" + requestId + " 已用于不同业务参数，拒绝处理");
        }
        try {
            Object body = objectMapper.readValue(row.responseBody(), Object.class);
            return new Outcome(row.statusCode(), body);
        } catch (Exception e) {
            throw new IllegalStateException("幂等响应反序列化失败", e);
        }
    }
    Outcome outcome = task.get();
    String bodyJson;
    try {
        bodyJson = objectMapper.writeValueAsString(outcome.body());
    } catch (Exception e) {
        throw new IllegalStateException("幂等响应序列化失败", e);
    }
    try {
        repo.insertIdempotent(requestId, action, fingerprint, planId, outcome.statusCode(),
                bodyJson, Instant.now(clock));
    } catch (DuplicateKeyException e) {
        // 并发同键：以已提交留痕为准
        IdempotentRow row = repo.findIdempotent(requestId)
                .orElseThrow(() -> new BusinessException(409, "幂等键并发冲突，请重试"));
        if (!row.fingerprint().equals(fingerprint)) {
            throw new BusinessException(409,
                    "requestId=" + requestId + " 已用于不同业务参数，拒绝处理");
        }
        try {
            return new Outcome(row.statusCode(), objectMapper.readValue(row.responseBody(), Object.class));
        } catch (Exception ex) {
            throw new IllegalStateException("幂等响应反序列化失败", ex);
        }
    }
    return outcome;
}

